Here's the recipe with middleware.

```ts
const immer = <T>(
  config: StateCreator<T, (fn: (state: T) => void) => void>
): StateCreator<T> => (set, get, api) => config(
  (fn) => set(produce(fn) as (state: T) => T),
  get,
  api
)

const useStore = create<{
  bees: boolean
  setBees: (b: boolean) => void
}>(
  immer((set) => ({
    bees: false,
    setBees: (input) =>
      set((state) => {
        state.bees = input
      }),
  }))
)
